#include <stdio.h>
#include <stdlib.h>
struct Node{int value;struct Node *next;};
void destroy(struct Node *p){while(p){struct Node *next=p->next;free(p);p=next;}}

int main(void) {
    struct Node *head=NULL;
    for(int i=3;i>=1;i--){struct Node *node=malloc(sizeof *node);if(!node){destroy(head);return 1;}node->value=i;node->next=head;head=node;}
    int total=0;for(struct Node *p=head;p;p=p->next)total+=p->value;
    printf("%d\n",total);destroy(head);
    return 0;
}

